  this.raycaster=new THREE.Raycaster();this.pointer=new THREE.Vector2();this.down=null;const canvas=this.renderer.domElement;canvas.setAttribute('aria-label','Drag to rotate the illustrative 3D view; scroll to zoom.');canvas.addEventListener('pointerdown',e=>{this.down=[e.clientX,e.clientY];});canvas.addEventListener('pointerup',e=>{if(!this.down)return;const d=Math.hypot(e.clientX-this.down[0],e.clientY-this.down[1]);this.down=null;if(d>5)return;const r=canvas.getBoundingClientRect();this.pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);this.raycaster.setFromCamera(this.pointer,this.camera);const hit=this.raycaster.intersectObject(this.root,true).find(h=>h.object.visible&&h.object.userData.ref&&this.visibleAncestors(h.object));if(hit){const data=hit.object.userData;this.onSelect(this.kind==='vehicle'?{system:data.systemId||data.ref}:{ref:data.ref});}});
