 positionLabels(){const bounds=this.mount.getBoundingClientRect();const occupied=[];for(const {n,button}of this.nodes||[]){const p=new THREE.Vector3();n.getWorldPosition(p);p.project(this.camera);const x=(p.x*.5+.5)*bounds.width,y=(-p.y*.5+.5)*bounds.height;let hide=!this.labelsEnabled||!n.visible||p.z>1||p.z< -1||x<10||x>bounds.width-10||y<10||y>bounds.height-10;const selected=n.userData.ref===this.selected;for(const [a,b]of occupied)if(!selected&&Math.hypot(x-a,y-b)<(this.kind==='vehicle'?50:22))hide=true;button.hidden=hide;if(!hide){occupied.push([x,y]);button.style.left=x+'px';button.style.top=y+'px';}}}
